function setupFinanceCollapsibles(){const root=$('finance');if(!root)return;root.querySelectorAll('.settingspanel').forEach(panel=>{if(panel.dataset.collapseReady)return;const title=panel.querySelector('h2');if(!title)return;panel.dataset.collapseReady='1';const head=title.closest('.panelhead')&&title.closest('.panelhead').parentElement===panel?title.closest('.panelhead'):title;const btn=document.createElement('button');btn.type='button';btn.className='secondary finance-collapse';btn.textContent='Minimalkan';btn.setAttribute('aria-expanded','true');head.insertAdjacentElement('afterend',btn);const nodes=[...panel.children].filter(n=>n!==head&&n!==btn);const wrap=document.createElement('div');wrap.className='finance-panel-body';nodes.forEach(n=>wrap.appendChild(n));panel.appendChild(wrap);btn.onclick=()=>{const closed=wrap.classList.toggle('collapsed');btn.textContent=closed?'Buka bagian':'Minimalkan';btn.setAttribute('aria-expanded',String(!closed))}})}
